/**
 * BPM 列表页取数（/files/infos/bpm.json）。
 */
import { loadJson } from './jsonCache.js'
import { NET, illLowPath } from './common.js'

export const BPM_PATH = `${NET}/files/infos/bpm.json`

/**
 * 递归把所有字符串值换成对应曲绘地址。
 * 该 json 里的叶子字符串都是曲目键名，页面直接当图片地址用。
 */
function transformSongPaths(data) {
  if (Array.isArray(data)) {
    return data.map((item) => transformSongPaths(item))
  }
  if (typeof data === 'object' && data !== null) {
    const newObj = {}
    for (const key in data) {
      newObj[key] = transformSongPaths(data[key])
    }
    return newObj
  }
  if (typeof data === 'string') {
    return illLowPath(data)
  }
  return data
}

export async function getBPM() {
  try {
    const jsonData = await loadJson(BPM_PATH)
    return transformSongPaths(jsonData)
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', BPM_PATH)
    return {}
  }
}
